     1→# ================================================================
     2→# FreeLang Bootstrap Parser (Week 2, Phase B-4)
     3→# TypeScript parser.ts → FreeLang parser.fl 변환
     4→# 토큰 → AST (Abstract Syntax Tree) 변환
     5→#
     6→# 구조:
     7→# 1. AST 노드 생성 함수들
     8→# 2. Parser 상태 관리
     9→# 3. parse() - 진입점
    10→# 4. statement() - 문장 파싱
    11→# 5. expression() - 식 파싱 (우선순위)
    12→# ================================================================
    13→
    14→# ================================================================
    15→# AST 노드 생성 함수들 (12+ 타입)
    16→# ================================================================
    17→
    18→# Statement 노드들
    19→fn createAssignment(variable: string, value: {}) {
    20→  return { "type": "assignment", "variable": variable, "value": value }
    21→}
    22→
    23→fn createFunctionDefinition(name: string, params: [], body: []) {
    24→  return { "type": "functionDefinition", "name": name, "params": params, "body": body }
    25→}
    26→
    27→fn createIfStatement(condition: {}, thenBranch: [], elseBranch: []) {
    28→  return { "type": "ifStatement", "condition": condition, "then": thenBranch, "else": elseBranch }
    29→}
    30→
    31→fn createWhileStatement(condition: {}, body: []) {
    32→  return { "type": "whileStatement", "condition": condition, "body": body }
    33→}
    34→
    35→fn createReturnStatement(value: {}) {
    36→  return { "type": "returnStatement", "value": value }
    37→}
    38→
    39→fn createBlockStatement(statements: []) {
    40→  return { "type": "blockStatement", "statements": statements }
    41→}
    42→
    43→# Expression 노드들
    44→fn createBinaryOp(left: {}, operator: string, right: {}) {
    45→  return { "type": "binaryOp", "left": left, "operator": operator, "right": right }
    46→}
    47→
    48→fn createUnaryOp(operator: string, operand: {}) {
    49→  return { "type": "unaryOp", "operator": operator, "operand": operand }
    50→}
    51→
    52→fn createCallExpression(callee: {}, args: []) {
    53→  return { "type": "call", "callee": callee, "arguments": args }
    54→}
    55→
    56→fn createIdentifier(name: string) {
    57→  return { "type": "identifier", "name": name }
    58→}
    59→
    60→fn createLiteral(value: {}, literalType: string) {
    61→  return { "type": "literal", "value": value, "literalType": literalType }
    62→}
    63→
    64→fn createArrayLiteral(elements: []) {
    65→  return { "type": "arrayLiteral", "elements": elements }
    66→}
    67→
    68→fn createArrayAccess(array: {}, index: {}) {
    69→  return { "type": "arrayAccess", "array": array, "index": index }
    70→}
    71→
    72→fn createArrayAssignment(array: {}, index: {}, value: {}) {
    73→  return { "type": "arrayAssignment", "array": array, "index": index, "value": value }
    74→}
    75→
    76→fn createMemberAssignment(object: {}, property: string, value: {}) {
    77→  return { "type": "memberAssignment", "object": object, "property": property, "value": value }
    78→}
    79→
    80→fn createForInStatement(variable: string, iterable: {}, body: []) {
    81→  return { "type": "forInStatement", "variable": variable, "iterable": iterable, "body": body }
    82→}
    83→
    84→fn createDictLiteral(pairs: []) {
    85→  return { "type": "dictLiteral", "pairs": pairs }
    86→}
    87→
    88→fn createMemberAccess(object: {}, property: string) {
    89→  return { "type": "memberAccess", "object": object, "property": property }
    90→}
    91→
    92→fn createStructDefinition(name: string, fields: []) {
    93→  return { "type": "structDefinition", "name": name, "fields": fields }
    94→}
    95→
    96→# ================================================================
    97→# Parser 상태 관리
    98→# ================================================================
    99→
   100→fn createParserState(tokens: []) {
   101→  return {
   102→    "tokens": tokens,
   103→    "position": 0
   104→  }
   105→}
   106→
   107→# 현재 토큰 접근
   108→fn currentToken(state: {}) {
   109→  if state["position"] < len(state["tokens"]) {
   110→    return state["tokens"][state["position"]]
   111→  }
   112→  return { "type": "eof", "value": "" }
   113→}
   114→
   115→# 다음 토큰 미리보기
   116→fn peekToken(state: {}, offset: int) {
   117→  pos = state["position"] + offset
   118→  if pos < len(state["tokens"]) {
   119→    return state["tokens"][pos]
   120→  }
   121→  return { "type": "eof", "value": "" }
   122→}
   123→
   124→# 토큰 이동
   125→fn advance(state: {}) {
   126→  state["position"] = state["position"] + 1
   127→  return state
   128→}
   129→
   130→# 토큰 매칭
   131→fn match(state: {}, expectedType: string, expectedValue: string) {
   132→  token = currentToken(state)
   133→  if token["type"] == expectedType and (expectedValue == "" or token["value"] == expectedValue) {
   134→    state = advance(state)
   135→    return { "matched": true, "state": state, "token": token }
   136→  }
   137→  return { "matched": false, "state": state, "token": null }
   138→}
   139→
   140→# ================================================================
   141→# Parse 진입점 (메인 함수)
   142→# ================================================================
   143→
   144→fn parse(tokens: []) {
   145→  state = createParserState(tokens)
   146→  statements = []
   147→
   148→  # 메인 루프: EOF까지 문장 파싱
   149→  while currentToken(state)["type"] != "eof" {
   150→    # 빈 줄 건너뛰기
   151→    if currentToken(state)["type"] == "newline" {
   152→      state = advance(state)
   153→    }
   154→    else {
   155→      stmt = parseStatement(state)
   156→      if stmt != null {
   157→        statements = statements + [stmt]
   158→      }
   159→      state = stmt["_state"]
   160→    }
   161→  }
   162→
   163→  return statements
   164→}
   165→
   166→# ================================================================
   167→# Statement 파싱
   168→# ================================================================
   169→
   170→fn parseStatement(state: {}) {
   171→  token = currentToken(state)
   172→
   173→  # 함수 정의
   174→  if token["type"] == "keyword" and token["value"] == "fn" {
   175→    return parseFunctionDefinition(state)
   176→  }
   177→  # struct 정의
   178→  else if token["type"] == "keyword" and token["value"] == "struct" {
   179→    return parseStructDefinition(state)
   180→  }
   181→  # if 문
   182→  else if token["type"] == "keyword" and token["value"] == "if" {
   183→    return parseIfStatement(state)
   184→  }
   185→  # while 루프
   186→  else if token["type"] == "keyword" and token["value"] == "while" {
   187→    return parseWhileStatement(state)
   188→  }
   189→  # for-in 루프
   190→  else if token["type"] == "keyword" and token["value"] == "for" {
   191→    return parseForInStatement(state)
   192→  }
   193→  # return 문
   194→  else if token["type"] == "keyword" and token["value"] == "return" {
   195→    return parseReturnStatement(state)
   196→  }
   197→  # 블록
   198→  else if token["type"] == "lbrace" {
   199→    return parseBlockStatement(state)
   200→  }
   201→  # 식 문장
   202→  else {
   203→    return parseExpressionStatement(state)
   204→  }
   205→}
   206→
   207→# 식 문장
   208→fn parseExpressionStatement(state: {}) {
   209→  expr = parseExpression(state)
   210→  state = expr["_state"]
   211→
   212→  # 세미콜론 또는 줄바꿈 선택적
   213→  if currentToken(state)["type"] == "semicolon" {
   214→    state = advance(state)
   215→  }
   216→  else if currentToken(state)["type"] == "newline" {
   217→    state = advance(state)
   218→  }
   219→
   220→  return { "_state": state, "result": expr }
   221→}
   222→
   223→# 함수 정의
   224→fn parseFunctionDefinition(state: {}) {
   225→  # fn 키워드 건너뛰기
   226→  state = advance(state)
   227→
   228→  # 함수 이름
   229→  nameToken = currentToken(state)
   230→  if nameToken["type"] != "identifier" {
   231→    print("Expected identifier after 'fn'")
   232→    return { "_state": state, "result": null }
   233→  }
   234→  funcName = nameToken["value"]
   235→  state = advance(state)
   236→
   237→  # 매개변수 목록
   238→  params = []
   239→  if currentToken(state)["type"] == "lparen" {
   240→    state = advance(state)
   241→
   242→    while currentToken(state)["type"] != "rparen" {
   243→      paramToken = currentToken(state)
   244→      if paramToken["type"] == "identifier" {
   245→        params = params + [paramToken["value"]]
   246→        state = advance(state)
   247→
   248→        # 타입 주석 건너뛰기 (optional)
   249→        if currentToken(state)["type"] == "colon" {
   250→          state = advance(state)
   251→          # 타입 정보 무시
   252→          state = advance(state)
   253→        }
   254→
   255→        # 쉼표
   256→        if currentToken(state)["type"] == "comma" {
   257→          state = advance(state)
   258→        }
   259→      }
   260→      else {
   261→        print("Expected parameter name")
   262→        state = advance(state)
   263→      }
   264→    }
   265→
   266→    state = advance(state)  # rparen
   267→  }
   268→
   269→  # 함수 본문
   270→  body = []
   271→  if currentToken(state)["type"] == "lbrace" {
   272→    blockStmt = parseBlockStatement(state)
   273→    state = blockStmt["_state"]
   274→    body = blockStmt["result"]["statements"]
   275→  }
   276→
   277→  funcDef = createFunctionDefinition(funcName, params, body)
   278→  return { "_state": state, "result": funcDef }
   279→}
   280→
   281→# struct 정의
   282→fn parseStructDefinition(state: {}) {
   283→  # struct 키워드 건너뛰기
   284→  state = advance(state)
   285→
   286→  # struct 이름
   287→  nameToken = currentToken(state)
   288→  if nameToken["type"] != "identifier" {
   289→    print("Expected identifier after 'struct'")
   290→    return { "_state": state, "result": null }
   291→  }
   292→  structName = nameToken["value"]
   293→  state = advance(state)
   294→
   295→  # 필드 정의 ({})
   296→  fields = []
   297→  if currentToken(state)["type"] == "lbrace" {
   298→    state = advance(state)
   299→
   300→    while currentToken(state)["type"] != "rbrace" and currentToken(state)["type"] != "eof" {
   301→      # 필드명
   302→      fieldToken = currentToken(state)
   303→      if fieldToken["type"] == "identifier" {
   304→        fieldName = fieldToken["value"]
   305→        state = advance(state)
   306→
   307→        # 타입 주석 (필수)
   308→        if currentToken(state)["type"] == "colon" {
   309→          state = advance(state)
   310→          typeToken = currentToken(state)
   311→          fieldType = typeToken["value"]
   312→          state = advance(state)
   313→
   314→          # 필드 추가
   315→          fields = fields + [{ "name": fieldName, "type": fieldType }]
   316→        }
   317→
   318→        # 쉼표
   319→        if currentToken(state)["type"] == "comma" {
   320→          state = advance(state)
   321→        }
   322→      }
   323→      else {
   324→        print("Expected field name in struct definition")
   325→        break
   326→      }
   327→    }
   328→
   329→    if currentToken(state)["type"] == "rbrace" {
   330→      state = advance(state)
   331→    }
   332→  }
   333→
   334→  structDef = createStructDefinition(structName, fields)
   335→  return { "_state": state, "result": structDef }
   336→}
   337→
   338→# if 문
   339→fn parseIfStatement(state: {}) {
   340→  # if 키워드 건너뛰기
   341→  state = advance(state)
   342→
   343→  # 조건
   344→  condition = parseExpression(state)
   345→  state = condition["_state"]
   346→
   347→  # then 블록
   348→  thenBlock = parseBlockStatement(state)
   349→  state = thenBlock["_state"]
   350→  thenBranch = thenBlock["result"]["statements"]
   351→
   352→  # else 블록 (optional)
   353→  elseBranch = []
   354→  if currentToken(state)["type"] == "keyword" and currentToken(state)["value"] == "else" {
   355→    state = advance(state)
   356→
   357→    elseBlock = parseBlockStatement(state)
   358→    state = elseBlock["_state"]
   359→    elseBranch = elseBlock["result"]["statements"]
   360→  }
   361→
   362→  ifStmt = createIfStatement(condition, thenBranch, elseBranch)
   363→  return { "_state": state, "result": ifStmt }
   364→}
   365→
   366→# while 루프
   367→fn parseWhileStatement(state: {}) {
   368→  # while 키워드 건너뛰기
   369→  state = advance(state)
   370→
   371→  # 조건
   372→  condition = parseExpression(state)
   373→  state = condition["_state"]
   374→
   375→  # 루프 본문
   376→  body = []
   377→  if currentToken(state)["type"] == "lbrace" {
   378→    blockStmt = parseBlockStatement(state)
   379→    state = blockStmt["_state"]
   380→    body = blockStmt["result"]["statements"]
   381→  }
   382→
   383→  whileStmt = createWhileStatement(condition, body)
   384→  return { "_state": state, "result": whileStmt }
   385→}
   386→
   387→# for-in 루프
   388→fn parseForInStatement(state: {}) {
   389→  # for 키워드 건너뛰기
   390→  state = advance(state)
   391→
   392→  # 루프 변수
   393→  varToken = currentToken(state)
   394→  if varToken["type"] != "identifier" {
   395→    print("Expected identifier after 'for'")
   396→    return { "_state": state, "result": null }
   397→  }
   398→  varName = varToken["value"]
   399→  state = advance(state)
   400→
   401→  # in 키워드
   402→  if currentToken(state)["type"] != "keyword" or currentToken(state)["value"] != "in" {
   403→    print("Expected 'in' in for-in loop")
   404→    return { "_state": state, "result": null }
   405→  }
   406→  state = advance(state)
   407→
   408→  # 반복 가능한 식 (배열 또는 range)
   409→  iterable = parseExpression(state)
   410→  state = iterable["_state"]
   411→
   412→  # 루프 본문
   413→  body = []
   414→  if currentToken(state)["type"] == "lbrace" {
   415→    blockStmt = parseBlockStatement(state)
   416→    state = blockStmt["_state"]
   417→    body = blockStmt["result"]["statements"]
   418→  }
   419→
   420→  forInStmt = createForInStatement(varName, iterable, body)
   421→  return { "_state": state, "result": forInStmt }
   422→}
   423→
   424→# return 문
   425→fn parseReturnStatement(state: {}) {
   426→  # return 키워드 건너뛰기
   427→  state = advance(state)
   428→
   429→  # 반환값 (optional)
   430→  value = null
   431→  if currentToken(state)["type"] != "newline" and currentToken(state)["type"] != "eof" {
   432→    exprResult = parseExpression(state)
   433→    state = exprResult["_state"]
   434→    value = exprResult
   435→  }
   436→
   437→  retStmt = createReturnStatement(value)
   438→  return { "_state": state, "result": retStmt }
   439→}
   440→
   441→# 블록 문
   442→fn parseBlockStatement(state: {}) {
   443→  if currentToken(state)["type"] != "lbrace" {
   444→    print("Expected '{'")
   445→    return { "_state": state, "result": { "type": "blockStatement", "statements": [] } }
   446→  }
   447→
   448→  state = advance(state)  # lbrace
   449→  statements = []
   450→
   451→  while currentToken(state)["type"] != "rbrace" and currentToken(state)["type"] != "eof" {
   452→    if currentToken(state)["type"] == "newline" {
   453→      state = advance(state)
   454→    }
   455→    else {
   456→      stmt = parseStatement(state)
   457→      if stmt != null {
   458→        statements = statements + [stmt["result"]]
   459→      }
   460→      state = stmt["_state"]
   461→    }
   462→  }
   463→
   464→  if currentToken(state)["type"] == "rbrace" {
   465→    state = advance(state)
   466→  }
   467→
   468→  blockStmt = createBlockStatement(statements)
   469→  return { "_state": state, "result": blockStmt }
   470→}
   471→
   472→# ================================================================
   473→# Expression 파싱 (우선순위 기반)
   474→# ================================================================
   475→
   476→# 최상위 (낮은 우선순위)
   477→fn parseExpression(state: {}) {
   478→  return parseAssignment(state)
   479→}
   480→
   481→# 할당 (= 연산자)
   482→fn parseAssignment(state: {}) {
   483→  expr = parseOr(state)
   484→  state = expr["_state"]
   485→
   486→  if currentToken(state)["type"] == "equals" {
   487→    state = advance(state)
   488→
   489→    # 좌변이 identifier, arrayAccess, 또는 memberAccess
   490→    if expr["type"] == "identifier" {
   491→      value = parseAssignment(state)
   492→      state = value["_state"]
   493→
   494→      assignment = createAssignment(expr["name"], value)
   495→      return { "_state": state, "result": assignment }
   496→    }
   497→    else if expr["type"] == "arrayAccess" {
   498→      value = parseAssignment(state)
   499→      state = value["_state"]
   500→
   501→      assignment = createArrayAssignment(expr["array"], expr["index"], value)
   502→      return { "_state": state, "result": assignment }
   503→    }
   504→    else if expr["type"] == "memberAccess" {
   505→      value = parseAssignment(state)
   506→      state = value["_state"]
   507→
   508→      assignment = createMemberAssignment(expr["object"], expr["property"], value)
   509→      return { "_state": state, "result": assignment }
   510→    }
   511→  }
   512→
   513→  return { "_state": state, "result": expr }
   514→}
   515→
   516→# OR 연산자 (||)
   517→fn parseOr(state: {}) {
   518→  left = parseAnd(state)
   519→  state = left["_state"]
   520→
   521→  while currentToken(state)["type"] == "operator" and currentToken(state)["value"] == "||" {
   522→    state = advance(state)
   523→    right = parseAnd(state)
   524→    state = right["_state"]
   525→
   526→    left = createBinaryOp(left, "||", right)
   527→  }
   528→
   529→  return { "_state": state, "result": left }
   530→}
   531→
   532→# AND 연산자 (&&)
   533→fn parseAnd(state: {}) {
   534→  left = parseEquality(state)
   535→  state = left["_state"]
   536→
   537→  while currentToken(state)["type"] == "operator" and currentToken(state)["value"] == "&&" {
   538→    state = advance(state)
   539→    right = parseEquality(state)
   540→    state = right["_state"]
   541→
   542→    left = createBinaryOp(left, "&&", right)
   543→  }
   544→
   545→  return { "_state": state, "result": left }
   546→}
   547→
   548→# 동등성 (==, !=)
   549→fn parseEquality(state: {}) {
   550→  left = parseComparison(state)
   551→  state = left["_state"]
   552→
   553→  while currentToken(state)["type"] == "operator" and
   554→        (currentToken(state)["value"] == "==" or currentToken(state)["value"] == "!=") {
   555→    op = currentToken(state)["value"]
   556→    state = advance(state)
   557→
   558→    right = parseComparison(state)
   559→    state = right["_state"]
   560→
   561→    left = createBinaryOp(left, op, right)
   562→  }
   563→
   564→  return { "_state": state, "result": left }
   565→}
   566→
   567→# 비교 (<, <=, >, >=)
   568→fn parseComparison(state: {}) {
   569→  left = parseAddition(state)
   570→  state = left["_state"]
   571→
   572→  while currentToken(state)["type"] == "operator" and
   573→        (currentToken(state)["value"] == "<" or
   574→         currentToken(state)["value"] == "<=" or
   575→         currentToken(state)["value"] == ">" or
   576→         currentToken(state)["value"] == ">=") {
   577→    op = currentToken(state)["value"]
   578→    state = advance(state)
   579→
   580→    right = parseAddition(state)
   581→    state = right["_state"]
   582→
   583→    left = createBinaryOp(left, op, right)
   584→  }
   585→
   586→  return { "_state": state, "result": left }
   587→}
   588→
   589→# 덧셈 (+, -)
   590→fn parseAddition(state: {}) {
   591→  left = parseMultiplication(state)
   592→  state = left["_state"]
   593→
   594→  while currentToken(state)["type"] == "operator" and
   595→        (currentToken(state)["value"] == "+" or currentToken(state)["value"] == "-") {
   596→    op = currentToken(state)["value"]
   597→    state = advance(state)
   598→
   599→    right = parseMultiplication(state)
   600→    state = right["_state"]
   601→
   602→    left = createBinaryOp(left, op, right)
   603→  }
   604→
   605→  return { "_state": state, "result": left }
   606→}
   607→
   608→# 곱셈 (*, /, %)
   609→fn parseMultiplication(state: {}) {
   610→  left = parseUnary(state)
   611→  state = left["_state"]
   612→
   613→  while currentToken(state)["type"] == "operator" and
   614→        (currentToken(state)["value"] == "*" or
   615→         currentToken(state)["value"] == "/" or
   616→         currentToken(state)["value"] == "%") {
   617→    op = currentToken(state)["value"]
   618→    state = advance(state)
   619→
   620→    right = parseUnary(state)
   621→    state = right["_state"]
   622→
   623→    left = createBinaryOp(left, op, right)
   624→  }
   625→
   626→  return { "_state": state, "result": left }
   627→}
   628→
   629→# 단항 연산 (-, !, &, &mut)
   630→fn parseUnary(state: {}) {
   631→  if currentToken(state)["type"] == "operator" and
   632→     (currentToken(state)["value"] == "-" or
   633→      currentToken(state)["value"] == "!" or
   634→      currentToken(state)["value"] == "&") {
   635→    op = currentToken(state)["value"]
   636→    state = advance(state)
   637→
   638→    # &mut 처리
   639→    if op == "&" and currentToken(state)["type"] == "keyword" and currentToken(state)["value"] == "mut" {
   640→      state = advance(state)
   641→      op = "&mut"
   642→    }
   643→
   644→    operand = parseUnary(state)
   645→    state = operand["_state"]
   646→
   647→    unary = createUnaryOp(op, operand)
   648→    return { "_state": state, "result": unary }
   649→  }
   650→
   651→  return parseCall(state)
   652→}
   653→
   654→# 함수 호출 (()) + 멤버 접근 (.)
   655→fn parseCall(state: {}) {
   656→  expr = parsePrimary(state)
   657→  state = expr["_state"]
   658→
   659→  while true {
   660→    if currentToken(state)["type"] == "lparen" {
   661→      # 함수 호출
   662→      state = advance(state)
   663→      args = []
   664→
   665→      while currentToken(state)["type"] != "rparen" {
   666→        arg = parseExpression(state)
   667→        state = arg["_state"]
   668→        args = args + [arg]
   669→
   670→        if currentToken(state)["type"] == "comma" {
   671→          state = advance(state)
   672→        }
   673→      }
   674→
   675→      state = advance(state)  # rparen
   676→      expr = createCallExpression(expr, args)
   677→    }
   678→    else if currentToken(state)["type"] == "lbracket" {
   679→      # 배열 접근 ([])
   680→      state = advance(state)
   681→      index = parseExpression(state)
   682→      state = index["_state"]
   683→
   684→      if currentToken(state)["type"] == "rbracket" {
   685→        state = advance(state)
   686→      }
   687→
   688→      expr = createArrayAccess(expr, index)
   689→    }
   690→    else if currentToken(state)["type"] == "dot" {
   691→      # 멤버 접근 (.)
   692→      state = advance(state)
   693→      propToken = currentToken(state)
   694→
   695→      if propToken["type"] == "identifier" {
   696→        propName = propToken["value"]
   697→        state = advance(state)
   698→        expr = createMemberAccess(expr, propName)
   699→      } else {
   700→        print("Expected property name after '.'")
   701→        break
   702→      }
   703→    }
   704→    else {
   705→      break
   706→    }
   707→  }
   708→
   709→  return { "_state": state, "result": expr }
   710→}
   711→
   712→# 기본 표현식
   713→fn parsePrimary(state: {}) {
   714→  token = currentToken(state)
   715→
   716→  # 숫자
   717→  if token["type"] == "number" {
   718→    state = advance(state)
   719→    return { "_state": state, "result": createLiteral(token["value"], "number") }
   720→  }
   721→  # 문자열
   722→  else if token["type"] == "string" {
   723→    state = advance(state)
   724→    return { "_state": state, "result": createLiteral(token["value"], "string") }
   725→  }
   726→  # true, false
   727→  else if token["type"] == "keyword" and (token["value"] == "true" or token["value"] == "false") {
   728→    state = advance(state)
   729→    return { "_state": state, "result": createLiteral(token["value"], "boolean") }
   730→  }
   731→  # null
   732→  else if token["type"] == "keyword" and token["value"] == "null" {
   733→    state = advance(state)
   734→    return { "_state": state, "result": createLiteral(null, "null") }
   735→  }
   736→  # 배열 리터럴 ([])
   737→  else if token["type"] == "lbracket" {
   738→    state = advance(state)
   739→    elements = []
   740→
   741→    while currentToken(state)["type"] != "rbracket" {
   742→      elem = parseExpression(state)
   743→      state = elem["_state"]
   744→      elements = elements + [elem]
   745→
   746→      if currentToken(state)["type"] == "comma" {
   747→        state = advance(state)
   748→      }
   749→    }
   750→
   751→    state = advance(state)  # rbracket
   752→    return { "_state": state, "result": createArrayLiteral(elements) }
   753→  }
   754→  # 딕셔너리 리터럴 ({})
   755→  else if token["type"] == "lbrace" {
   756→    state = advance(state)
   757→    pairs = []
   758→
   759→    while currentToken(state)["type"] != "rbrace" and currentToken(state)["type"] != "eof" {
   760→      # 키 (문자열 또는 식별자)
   761→      keyToken = currentToken(state)
   762→      let key = null
   763→
   764→      if keyToken["type"] == "string" {
   765→        key = keyToken["value"]
   766→        state = advance(state)
   767→      } else if keyToken["type"] == "identifier" {
   768→        key = keyToken["value"]
   769→        state = advance(state)
   770→      } else {
   771→        print("Expected key in dictionary literal")
   772→        break
   773→      }
   774→
   775→      # 콜론
   776→      if currentToken(state)["type"] != "colon" {
   777→        print("Expected ':' after dictionary key")
   778→        break
   779→      }
   780→      state = advance(state)
   781→
   782→      # 값
   783→      value = parseExpression(state)
   784→      state = value["_state"]
   785→
   786→      # 키-값 쌍 추가
   787→      pairs = pairs + [{ "key": key, "value": value }]
   788→
   789→      # 쉼표 또는 종료
   790→      if currentToken(state)["type"] == "comma" {
   791→        state = advance(state)
   792→      }
   793→      else if currentToken(state)["type"] == "rbrace" {
   794→        break
   795→      }
   796→    }
   797→
   798→    if currentToken(state)["type"] == "rbrace" {
   799→      state = advance(state)
   800→    }
   801→
   802→    return { "_state": state, "result": createDictLiteral(pairs) }
   803→  }
   804→  # 괄호 표현식
   805→  else if token["type"] == "lparen" {
   806→    state = advance(state)
   807→    expr = parseExpression(state)
   808→    state = expr["_state"]
   809→
   810→    if currentToken(state)["type"] == "rparen" {
   811→      state = advance(state)
   812→    }
   813→
   814→    return { "_state": state, "result": expr }
   815→  }
   816→  # 식별자
   817→  else if token["type"] == "identifier" {
   818→    state = advance(state)
   819→    return { "_state": state, "result": createIdentifier(token["value"]) }
   820→  }
   821→  else {
   822→    print("Unexpected token: " + token["type"])
   823→    return { "_state": state, "result": null }
   824→  }
   825→}
