   274→function exec(command) {
   275→  try {
   276→    const result = execSync(command, {
   277→      encoding: 'utf8',
   278→      stdio: ['pipe', 'pipe', 'pipe'],
   279→    });
   280→
   281→    return {
   282→      ok: true,
   283→      stdout: result,
   284→      stderr: '',
   285→      code: 0,
   286→      error: null,
   287→    };
   288→  } catch (err) {
   289→    return {
   290→      ok: false,
   291→      stdout: err.stdout || '',
   292→      stderr: err.stderr || '',
   293→      code: err.status || 1,
   294→      error: err.message,
   295→    };
